internal readonly struct OnHitGraft
{
	internal readonly string BuffSid;
	internal readonly int Duration;
	internal readonly string AttackTag;

	internal OnHitGraft(string buffSid, int duration, string attackTag)
	{
		BuffSid = buffSid;
		Duration = duration;
		AttackTag = attackTag;
	}
}

internal readonly struct VampirismGraft
{
	internal readonly float Rate;
	internal readonly string Target;
	internal readonly string HealType;

	internal VampirismGraft(float rate, string target, string healType)
	{
		Rate = rate;
		Target = target;
		HealType = healType;
	}
}

internal readonly struct BattleStartGraft
{
	internal readonly string Kind;
	internal readonly string[] Keys;
	internal readonly string[] BuffSids;
	internal readonly int Duration;

	internal BattleStartGraft(string kind, string[] keys, string[] buffSids, int duration)
	{
		Kind = kind;
		Keys = keys;
		BuffSids = buffSids;
		Duration = duration;
	}
}

internal readonly struct MapHeroBuffGraft
{
	internal readonly string BuffSid;
	internal readonly string[] NativeUnitSids;

	internal MapHeroBuffGraft(string buffSid, string[] nativeUnitSids)
	{
		BuffSid = buffSid;
		NativeUnitSids = nativeUnitSids;
	}
}

internal readonly struct InjectedAbilityGraft
{
	internal readonly string SourceUnitSid;
	internal readonly int SourceIndex;
	internal readonly string LogicJson;
	internal readonly string ViewJson;

	internal InjectedAbilityGraft(string sourceUnitSid, int sourceIndex, string logicJson, string viewJson)
	{
		SourceUnitSid = sourceUnitSid;
		SourceIndex = sourceIndex;
		LogicJson = logicJson;
		ViewJson = viewJson;
	}
}

internal readonly struct ObservedPassiveAction
{
	internal readonly int Passive;
	internal readonly int Action;
	internal readonly int Schematic;
	internal readonly string Trigger;

	internal ObservedPassiveAction(int passive, int action, int schematic, string trigger)
	{
		Passive = passive;
		Action = action;
		Schematic = schematic;
		Trigger = trigger;
	}
}
